146: 	unsigned long r;
147: 
148: 	if (dp->lasthalf) {
149: 		r = dp->lasthalf;
150: 		dp->lasthalf = 0;
151: 	} else {
152: 		r = LRAND();
153: 		dp->lasthalf = (short) (r >> 16);
154: 	}
155: 	r = r % mv;
156: 	return r;
157: }
